package app.organicmaps.sdk.transit.rt;

import static org.junit.Assert.*;

import java.io.InputStream;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

/** Synthetic malformed inputs plus golden bytes generated by canonical protoc, not our field map. */
public class CanonicalRealtimeTest
{
  private byte[] golden(String name) throws Exception
  {
    try (InputStream in = getClass().getResourceAsStream("/transit/" + name))
    {
      assertNotNull(in);
      return in.readAllBytes();
    }
  }

  @Test public void canonicalVehicleTimestampAndDelayAreIndependent() throws Exception
  {
    GtfsRealtime.FeedMessage feed = GtfsRealtime.parse(golden("canonical-feed.pb"));
    assertEquals(Long.valueOf(1791880000L), feed.timestamp);
    GtfsRealtime.TripUpdate trip = feed.tripUpdates.get(0);
    assertEquals("T100", trip.tripId);
    assertEquals("20261013", trip.startDate);
    assertEquals(Long.valueOf(1791880000L), trip.timestamp);
    assertEquals(Long.valueOf(-60), trip.delay);
    assertEquals(Long.valueOf(1791880400L), trip.stopTimeUpdates.get(0).departure.time);
  }

  @Test(expected = WireReader.WireException.class)
  public void differentialFeedsCannotBeAppliedAsCompleteSnapshots() throws Exception
  {
    GtfsRealtime.parse(golden("canonical-differential.pb"));
  }

  @Test(expected = WireReader.WireException.class)
  public void timestampWithLengthDelimitedWireTypeIsRefused()
  {
    // FeedMessage.header: version="2.0", timestamp incorrectly encoded as string "a".
    GtfsRealtime.parse(new byte[]{10, 8, 10, 3, 50, 46, 48, 26, 1, 97});
  }

  @Test(expected = WireReader.WireException.class)
  public void overflowingTenthVarintByteIsRefused()
  {
    byte[] bytes = new byte[10];
    Arrays.fill(bytes, (byte) 0xff);
    bytes[9] = 2;
    new WireReader(bytes).readVarint();
  }

  @Test public void minimumLongCannotBypassDelayBounds()
  {
    assertFalse(RealtimeMerger.isPlausibleDelay(Long.MIN_VALUE));
    assertFalse(RealtimeMerger.isPlausibleDelay(Long.MAX_VALUE));
  }

  private GtfsRealtime.TripUpdate trip(int relationship, int stopRelationship)
  {
    GtfsRealtime.StopTimeUpdate stop = new GtfsRealtime.StopTimeUpdate("S", 1,
        null, null, stopRelationship);
    return new GtfsRealtime.TripUpdate("T", "R", null, null, relationship,
        0L, 1000L, Collections.singletonList(stop));
  }

  private RealtimeMerger.DepartureRow merge(GtfsRealtime.TripUpdate update)
  {
    return RealtimeMerger.mergeRow(new RealtimeMerger.ScheduledRow("T", "R", "D", "1", 1200, "S"),
        update, "S", 1000L, 1000L, 90, 600);
  }

  @Test public void explicitNoDataDoesNotFallBackToTripDelay()
  {
    assertEquals(RealtimeMerger.LiveState.SCHEDULED_ONLY, merge(trip(0, 2)).state);
  }

  @Test public void unsupportedStopRelationshipDoesNotClaimLive()
  {
    assertEquals(RealtimeMerger.LiveState.SCHEDULED_ONLY, merge(trip(0, 99)).state);
  }

  @Test public void unsupportedTripRelationshipDoesNotClaimLive()
  {
    assertEquals(RealtimeMerger.LiveState.SCHEDULED_ONLY, merge(trip(1, 0)).state);
  }

  @Test public void cancellationIsActuallyPositivelyTested()
  {
    assertEquals(RealtimeMerger.LiveState.CANCELED, merge(trip(3, 0)).state);
  }
}
